function storyForm20(){ return state.questPack?.storyForm20 || state.storyForm20 || null; }

function oneMainChipActive() {
  const day = state.save.dayIndex || 1;
  if (day >= 10) return true;
  if (["natural_ledger_street_wins","natural_ledger_street"].some(storyFlag)) return true;
  try {
    const w = pickUnifiedStoryWinner();
    if (w?.id === "ledger_natural") return true;
  } catch {}
  return false;
}

function mqStreetChipHtml() {
  if (oneMainChipActive()) {
    document.body.classList.add("rp-one-main-chip");
    return ""; // spineCultChipHtml owns MAIN 4/5 Ledger
  }
  const chips = (storyForm20()?.mqStreetChipsOverride || storyForm11()?.mqStreetChips || []);
  // prefer highest MAIN step: scan ledger first
  const ordered = [...chips].sort((a, b) => (b.stepRank || 0) - (a.stepRank || 0));
  const hit = ordered.find((c) => whenFlagsOk(c.when || {}));
  if (!hit) return "";
  return `<button class="rp-mq-street-chip" type="button" data-testid="${hit.testId}" data-action="open-quests">${loc(hit.chip)}</button>`;
}

// renderStreet: spineCultChipHtml() once; mqStreetChipHtml() returns '' on Day10
// syncLedgerWinsBodyClass already toggles rp-ledger-wins — CSS hides volume mq chip
